from pathlib import Path
import re
r=Path('docs/planning');files=[p for p in r.rglob('*.md') if 'archive' not in p.parts]
for p in files:
 t=p.read_text(encoding='utf-8'); issues=[]
 for m in re.finditer(r'\\]\\((["'^)#]+'"\\.md)(?:#["'^)]*)?'"\\)',t):
  q=p.parent/m.group(1)
  if not q.exists():issues.append(m.group(1))
 if issues:print(p.relative_to(r).as_posix(), 'BROKEN_LINKS',issues)
for p in files:
 t=p.read_text(encoding='utf-8')
 for m in re.finditer(r'"'`((?:archive|docs/spikes|evidence)/[''^`'"\\s,;)]+)',t):
  s=m.group(1).rstrip('.,')
  if '*' in s or '<' in s:continue
  if s.startswith('archive/'):
   if not (r/s).exists():print(p.relative_to(r).as_posix(),'BROKEN_ARCHIVE',s)
for p in files:
 t=p.read_text(encoding='utf-8')
 for m in re.finditer(r'(?:EVIDENCE_SPEC|ROUTING_POLICY|SECURITY_MODEL|TECH_STACK_DECISIONS|AGENT_INTEGRATION|PHASE_MANAGEMENT|COLLABORATION|SESSION_RECOVERY|EXECUTION_LIMITS|TEST_STRATEGY)\\s+§(\\d+(?:\\.\\d+)?)',t):
  prefix=m.group(0).split(' §')[0]; num=m.group(1)
  target=next((q for q in files if prefix in q.stem),None)
  if target is None:continue
  headings=target.read_text(encoding='utf-8')
  if not re.search(r'"'^#{2,6}'"\\s+'+re.escape(num)+r'(?:\\.|\\s)',headings,re.M):
   line=t[:m.start()].count('\\n')+1
   print(p.relative_to(r).as_posix(),line,'BAD_SECTION',prefix,num)
