from pathlib import Path
import re
r=Path('docs/planning');files=[p for p in r.rglob('*.md') if 'archive' not in p.parts]
for p in files:
 t=p.read_text(encoding='utf-8');hs=set(re.findall(r'"'^#{2,6}'"\\s+(\\d+(?:\\.\\d+)?)(?:\\.|\\s)',t,re.M))
 for i,line in enumerate(t.splitlines(),1):
  if '§' not in line:continue
  for m in re.finditer(r'§(\\d+(?:\\.\\d+)?)',line):
   num=m.group(1);pre=line[max(0,m.start()-75):m.start()]
   if re.search(r'[A-Z][A-Z_]+(?:\\.md)?\\s*"'$'"',pre):continue
   if num not in hs and not re.search(r'(지시서|기준 문서|SOURCES|DECISION_LOG|archive|SKILL|README|법|§)',pre[-40:]):
    if len(line)<350: print(p.relative_to(r).as_posix(),i,num,line[:140])
'@ | python -"

